import {quote} from './domain.mjs';
import {read} from './db.mjs';
export const run = () => quote('a',read);

import {price as retail} from './retail.mjs';
import {price as wholesale} from './wholesale.mjs';
export const observe = cents => [retail(cents),wholesale(cents)];

import {price as retail} from './retail.mjs';
import {price as wholesale} from './wholesale.mjs';
export const observe = cents => [retail(cents),wholesale(cents)];

import {price as retail} from './retail.mjs';
import {price as wholesale} from './wholesale.mjs';
export const observe = cents => [retail(cents),wholesale(cents)];

import assert from 'node:assert/strict';
import fs from 'node:fs';
assert.match(fs.readFileSync(new URL('./domain.mjs',import.meta.url),'utf8'), /const discount =/);

import assert from 'node:assert/strict';
import {quote} from './domain.mjs';
for(let cents=0;cents<=100;cents++)assert.equal(quote(cents),cents-cents*.1);

import assert from 'node:assert/strict';
import fs from 'node:fs';
assert.match(fs.readFileSync(new URL('./domain.mjs',import.meta.url),'utf8'), /const discount =/);

